#!/usr/bin/env python3
"""Run C1 Unit03 recalibration with narrow depth extensions that avoid new target forms."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c1_unit03.py')
text=SOURCE.read_text(encoding='utf-8')
patches={
"وإذا تحسن الرقم وحده، يصبح الانفصال نفسه دليلًا على أن التمثيل المؤسسي للنجاح يحتاج إلى مراجعة.''',":"وإذا تحسن الرقم وحده، يصبح الانفصال نفسه دليلًا على أن التمثيل المؤسسي للنجاح يحتاج إلى مراجعة. وأجرى الفريق مراجعة لاحقة بعد تغيير لوحة الأداء بثلاثة أشهر. لم يكتفوا بسؤال هل عادت المشكلة القديمة، بل بحثوا عن سلوك جديد يمكن أن ينشأ من الأوزان المختلفة للمؤشرات. وجدوا أن بعض الفرق بدأت تركز على الحالات التي تحسن أكثر من رقم في الوقت نفسه. لذلك أضافت هالة عينة نوعية دورية لا ترتبط مباشرة بالمكافأة، حتى يبقى لدى المؤسسة مصدر لا يتكيف معه الموظفون بالطريقة نفسها بسهولة. لم تعتبر هذا المصدر محايدًا تمامًا، لكنه وفر نقطة مقارنة مستقلة نسبيًا مع الأرقام اليومية.''',",
"بذلك صار قرار إضافة الموارد يأتي بعد فهم الحلقة لا قبلها.''',":"بذلك صار قرار إضافة الموارد يأتي بعد فهم الحلقة لا قبلها. كما قارنت الإدارة بين فرعين يملكان العدد نفسه من الخبراء لكنهما يستخدمان قواعد انتظار مختلفة. ظهر أن الفرع الذي ينشر تقديرًا أدق للوقت ويعيد توزيع الإلغاءات بسرعة يحتفظ بقائمة أقصر رغم تشابه القدرة الأساسية. لم تكن المقارنة تجربة كاملة، لكنها دعمت فكرة أن جزءًا من الضغط يصنعه النظام نفسه. لذلك أصبحت أي مطالبة بزيادة الموارد تتضمن أيضًا وصفًا لكيفية الحجز والإلغاء والمعلومات المتاحة للمستخدمين، حتى لا يُعالج السلوك الناتج من القاعدة بزيادة القدرة فقط.''',",
"إصلاح هذا الفرق قد يكون أكثر استدامة من إضافة بند جديد كلما ظهرت طريقة مختلفة للالتفاف.''',":"إصلاح هذا الفرق قد يكون أكثر استدامة من إضافة بند جديد كلما ظهرت طريقة مختلفة للالتفاف. وبعد تعديل الطريق العادي راقب الفريق هل انخفضت الحاجة إلى المسار السريع من تلقاء نفسها. إذا بقيت الحالات الخاصة مرتفعة رغم تبسيط الإجراء، فهذا دليل على أن المشكلة ليست فقط في الكلفة النسبية بين الطريقين. بهذه المقارنة استطاعوا فصل سببين كانا يبدوان متشابهين: قاعدة أساسية صعبة تدفع الناس إلى الطريق البديل، وحالات حقيقية تحتاج إلى معالجة مختلفة. جعل هذا الفصل الإصلاح أقل اعتمادًا على الاشتباه وأكثر اعتمادًا على نمط قابل للمراجعة.''',",
"والشفافية القوية لا تعد بأن كل صوت سيغير النتيجة؛ تعد بأن مسار التأثير والرفض والمراجعة سيكون مرئيًا بما يكفي ليعرف الناس أين يمكن تقديم دليل جديد.''',":"والشفافية القوية لا تعد بأن كل صوت سيغير النتيجة؛ تعد بأن مسار التأثير والرفض والمراجعة سيكون مرئيًا بما يكفي ليعرف الناس أين يمكن تقديم دليل جديد. وبعد انتهاء الأشهر الثلاثة نشر المجلس تقريرًا يقارن ما توقعه قبل التجربة بما حدث فعلًا، ويبين أي افتراضات تغيرت. ثم دعا عينة صغيرة من المستخدمين الذين لم يشاركوا سابقًا إلى مراجعة التقرير، لأن المجموعة الأولى قد تكون تعلمت لغة المؤسسة نفسها وأصبحت أقرب إلى طريقة تصنيفها للمشكلة. ظهرت ملاحظة جديدة عن أوقات الاستخدام لم تكن في القنوات السابقة، فأضيفت إلى دورة المراجعة التالية بدل إعادة كتابة القرار بأثر رجعي.''',",
"عندها يصبح الانحراف قابلًا للرؤية قبل أن يعاد تعريف الهدف بالكامل حول ما يسهل قياسه.''',":"عندها يصبح الانحراف قابلًا للرؤية قبل أن يعاد تعريف الهدف بالكامل حول ما يسهل قياسه. كما طلب المجلس من كل مؤشر أن يحمل «تاريخ استخدام» يبين السبب الذي أُدخل من أجله، والقرارات التي صار يؤثر فيها لاحقًا، وأي قيود على تفسيره. إذا بدأ رقم تشغيلي بسيط يدخل في التمويل أو تقييم الموظفين، تظهر هذه النقلة بوضوح وتحتاج إلى مراجعة مستقلة. ساعد السجل على منع انتقال الأدوات بهدوء من الوصف إلى الحوافز، وهو الانتقال الذي كان قد غيّر سلوك المؤسسة سابقًا من دون قرار صريح بتغيير رسالتها.''',",
"إنها تستخدمه اختبارًا مستمرًا لما صنعته قواعدها من فرص وتكاليف ومعلومات، ثم تعدل التصميم عندما تصبح الفجوة بين السلوك المرغوب والسلوك المعقول واسعة بما يكفي.''',":"إنها تستخدمه اختبارًا مستمرًا لما صنعته قواعدها من فرص وتكاليف ومعلومات، ثم تعدل التصميم عندما تصبح الفجوة بين السلوك المرغوب والسلوك المعقول واسعة بما يكفي. وفي مراجعة أخيرة طلبت هالة من فريق مستقل اختيار قاعدة واحدة ومحاولة التنبؤ بسلوكين معقولين قد تنتجهما قبل تطبيق أي تعديل جديد. لم يكن الهدف توقع كل تصرف، بل تدريب المؤسسة على سؤال كيف سيعيد الناس ترتيب خياراتهم عندما تتغير الكلفة والمكافأة والمعلومات. بعد التنفيذ قارن الفريق التوقعات بالسلوك الحقيقي وسجل ما فاته. بهذه الطريقة أصبح تصميم القاعدة نفسه عملية تعلم عن التكيف، لا مجرد كتابة نص ثم مراقبة الامتثال.''',",
}
for old,new in patches.items():
    assert text.count(old)==1, f'expected one retry insertion point: {old[:40]!r}'
    text=text.replace(old,new)
exec(compile(text,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
